    Mockito.verify(plainSocketFactory, Mockito.times(2)).createSocket(null, context);
    Mockito.verify(plainSocketFactory, Mockito.times(1)).connectSocket(socket, target, new InetSocketAddress(remote, 8443), new InetSocketAddress(local, 0), Timeout.ofMilliseconds(123), tlsConfig, context);
}

