@Test
public void testBasicAuthenticationCredentialsCaching() throws Exception {
    final ClassicTestServer server = startServer();
    server.registerHandler("*", new EchoHandler());
    final HttpHost target = targetHost();
    final DefaultAuthenticationStrategy authStrategy = Mockito.spy(new DefaultAuthenticationStrategy());
    final Queue<HttpResponse> responseQueue = new ConcurrentLinkedQueue<>();
    final CloseableHttpClient client = startClient(builder -> builder.setTargetAuthenticationStrategy(authStrategy).addResponseInterceptorLast((response, entity, context) -> responseQueue.add(BasicResponseBuilder.copy(response).build())));
    final HttpClientContext context = HttpClientContext.create();
    context.setCredentialsProvider(CredentialsProviderBuilder.create().add(target, "test", "test".toCharArray()).build());
    for (int i = 0; i < 5; i++) {
        final HttpGet httpget = new HttpGet("/");
        client.execute(target, httpget, context, response -> {
            final HttpEntity entity1 = response.getEntity();
            Assertions.assertEquals(HttpStatus.SC_OK, response.getCode());
            Assertions.assertNotNull(entity1);
            EntityUtils.consume(entity1);
            return null;
        });
    }
    Mockito.verify(authStrategy).select(Mockito.any(), Mockito.any(), Mockito.any());
    assertThat(responseQueue.stream().map(HttpResponse::getCode).collect(Collectors.toList()), CoreMatchers.equalTo(Arrays.asList(401, 200, 200, 200, 200, 200)));
}

